<script setup lang="ts">
import {ref,watch,nextTick} from 'vue';import {SelectRoot,SelectTrigger,SelectValue,SelectPortal,SelectContent,SelectViewport,SelectItem,SelectItemText} from 'reka-ui';
defineProps<{modelValue:number;theme:string}>();const emit=defineEmits<{'update:modelValue':[value:number]}>();const open=ref(false),scales=[25,33,50,67,75,80,90,100,110,125,150,175,200,250,300,400];
watch(open,async value=>{if(value){await nextTick();document.querySelector('.zoom-options [data-state="checked"]')?.scrollIntoView({block:'center'});}});
</script>
<template><SelectRoot v-model:open="open" :model-value="String(Math.round(modelValue*100))" @update:model-value="emit('update:modelValue',Number($event)/100)"><SelectTrigger class="problem-trigger" aria-label="界面缩放" :data-value="String(modelValue)"><SelectValue/><svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden="true"><path d="m3 5 4 4 4-4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></SelectTrigger><SelectPortal><SelectContent class="problem-options zoom-options" :data-theme="theme" position="popper" :side-offset="5"><SelectViewport style="max-height:224px;overflow:auto"><SelectItem v-for="n in scales" :key="n" :value="String(n)" class="problem-option"><SelectItemText>{{n}}%</SelectItemText></SelectItem></SelectViewport></SelectContent></SelectPortal></SelectRoot></template>
